  { id: "rejected", name: "淘汰", description: "本次流程已结束" }
];

const seedApplications = [
  { id: 1, company: "星云科技", role: "前端开发工程师", stage: "first-interview" },
  { id: 2, company: "远帆智能", role: "产品经理", stage: "screening" },
  { id: 3, company: "青屿数据", role: "数据分析师", stage: "offer" },
