const appJs = `const pipeline = document.querySelector("#pipeline");
const detailContent = document.querySelector("#detail-content");
const activeCount = document.querySelector("#active-count");
const applicationForm = document.querySelector("#application-form");
const companyInput = document.querySelector("#company-input");
const roleInput = document.querySelector("#role-input");
const stageInput = document.querySelector("#stage-input");
const formError = document.querySelector("#form-error");
const storageKey = "career-pipeline-applications";
const normalStageIds = ["applied", "screening", "first-interview", "second-interview", "offer"];

let applications = loadApplications();
let selectedId = applications[0]?.id ?? null;

stageInput.innerHTML = stages.map((stage) => \`<option value="\${stage.id}">\${stage.name}</option>\`).join("");

function loadApplications() {
  try {
    const storedApplications = JSON.parse(localStorage.getItem(storageKey));
    return Array.isArray(storedApplications) ? storedApplications : [...seedApplications];
  } catch {
    return [...seedApplications];
  }
}

function saveApplications() {
  localStorage.setItem(storageKey, JSON.stringify(applications));
}

function getStage(stageId) {
  return stages.find((stage) => stage.id === stageId);
}

function getNextStageId(stageId) {
  const currentIndex = normalStageIds.indexOf(stageId);
  return currentIndex >= 0 && currentIndex < normalStageIds.length - 1
    ? normalStageIds[currentIndex + 1]
    : null;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;"
  })[character]);
}

function renderPipeline() {
  pipeline.innerHTML = stages.map((stage, index) => {
    const cards = applications.filter((application) => application.stage === stage.id).map((application) => \`
      <button class="application-card \${application.id === selectedId ? "is-selected" : ""}" data-id="\${application.id}" type="button">
        <span class="company">\${escapeHtml(application.company)}</span>
        <span class="role">\${escapeHtml(application.role)}</span>
      </button>\`).join("");

    return \`
      <article class="stage \${stage.id}">
        <div class="stage-top"><span class="stage-index">0\${index + 1}</span><span class="node" aria-hidden="true"></span>\${index < stages.length - 1 ? '<span class="connector" aria-hidden="true"></span>' : ""}</div>
        <h3>\${stage.name}</h3><p>\${stage.description}</p>
        <div class="cards">\${cards || '<span class="empty-state">暂无记录</span>'}</div>
      </article>\`;
  }).join("");

  pipeline.querySelectorAll(".application-card").forEach((card) => {
    card.addEventListener("click", () => {
      selectedId = Number(card.dataset.id);
      render();
    });
  });
}

function renderDetail() {
  const application = applications.find((item) => item.id === selectedId);
  if (!application) {
    detailContent.innerHTML = '<p class="detail-note">请新增一条求职记录后查看详情。</p>';
    return;
  }

  const stage = getStage(application.stage);
  const nextStageId = getNextStageId(application.stage);
  detailContent.innerHTML = \`
    <div class="detail-mark">\${escapeHtml(application.company.slice(0, 1))}</div>
    <p class="detail-company">\${escapeHtml(application.company)}</p>
    <p class="detail-role">\${escapeHtml(application.role)}</p>
    <div class="current-stage"><span>当前阶段</span><strong>\${stage.name}</strong></div>
    <p class="detail-description">\${stage.description}</p>
    <button id="advance-button" class="advance-button" type="button" \${nextStageId ? "" : "disabled"}>
      \${nextStageId ? \`推进到\${getStage(nextStageId).name}\` : "已处于流程终点"}
    </button>
    <p class="detail-note">点击流程中的其他记录，可在此切换查看。</p>\`;

  const advanceButton = document.querySelector("#advance-button");
  if (nextStageId) {
    advanceButton.addEventListener("click", () => {
      application.stage = nextStageId;
      saveApplications();
      render();
    });
  }
}

function render() {
  activeCount.textContent = applications.filter((item) => !["rejected", "offer"].includes(item.stage)).length;
  renderPipeline();
  renderDetail();
}

applicationForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const company = companyInput.value.trim();
  const role = roleInput.value.trim();
  const stage = stageInput.value;

  if (!company || !role || !stage) {
    formError.textContent = "请填写公司名称、岗位名称，并选择当前阶段。";
    return;
  }

  const newApplication = { id: Date.now(), company, role, stage };
  applications.unshift(newApplication);
  selectedId = newApplication.id;
  saveApplications();
  applicationForm.reset();
  formError.textContent = "";
  render();
});

render();
`;
